window.ScripturaLexicons.BDAG_PART_0309 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-01\" data-source=\"BDAG\" data-search=\"προφέρω verbo produzir, trazer para fora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφέρω</td><td>verbo</td><td>produzir, trazer para fora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-02\" data-source=\"BDAG\" data-search=\"προφητεία, ας, ἡ substantivo feminino atividade profética, dom de profetizar, profecia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφητεία, ας, ἡ</td><td>substantivo feminino</td><td>atividade profética, dom de profetizar, profecia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-03\" data-source=\"BDAG\" data-search=\"προφητεύω verbo profetizar, revelar, predizer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφητεύω</td><td>verbo</td><td>profetizar, revelar, predizer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-04\" data-source=\"BDAG\" data-search=\"προφήτης, ου, ὁ substantivo masculino profeta; escritos proféticos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφήτης, ου, ὁ</td><td>substantivo masculino</td><td>profeta; escritos proféticos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-05\" data-source=\"BDAG\" data-search=\"προφητικός, ή, όν adjetivo profético BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφητικός, ή, όν</td><td>adjetivo</td><td>profético</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-06\" data-source=\"BDAG\" data-search=\"προφητικῶς advérbio profeticamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφητικῶς</td><td>advérbio</td><td>profeticamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-07\" data-source=\"BDAG\" data-search=\"προφῆτις, ιδος, ἡ substantivo feminino profetisa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφῆτις, ιδος, ἡ</td><td>substantivo feminino</td><td>profetisa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-08\" data-source=\"BDAG\" data-search=\"προφθάνω verbo preceder, antecipar-se, fazer previamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφθάνω</td><td>verbo</td><td>preceder, antecipar-se, fazer previamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-09\" data-source=\"BDAG\" data-search=\"προφυλάσσω verbo guardar, proteger, estar de sobreaviso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προφυλάσσω</td><td>verbo</td><td>guardar, proteger, estar de sobreaviso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-10\" data-source=\"BDAG\" data-search=\"προχειρίζω verbo escolher, selecionar, designar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προχειρίζω</td><td>verbo</td><td>escolher, selecionar, designar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-11\" data-source=\"BDAG\" data-search=\"προχειροτονέω verbo escolher ou designar previamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προχειροτονέω</td><td>verbo</td><td>escolher ou designar previamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-12\" data-source=\"BDAG\" data-search=\"Πρόχορος, ου, ὁ nome próprio masculino Prócoro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πρόχορος, ου, ὁ</td><td>nome próprio masculino</td><td>Prócoro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-13\" data-source=\"BDAG\" data-search=\"προχωρέω verbo avançar, sair-se bem, ter êxito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">προχωρέω</td><td>verbo</td><td>avançar, sair-se bem, ter êxito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-14\" data-source=\"BDAG\" data-search=\"πρύμνα, ης, ἡ substantivo feminino popa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρύμνα, ης, ἡ</td><td>substantivo feminino</td><td>popa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-15\" data-source=\"BDAG\" data-search=\"πρωί̈ advérbio cedo, de manhã cedo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωί̈</td><td>advérbio</td><td>cedo, de manhã cedo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-16\" data-source=\"BDAG\" data-search=\"πρωί̈α, ας, ἡ substantivo feminino manhã, manhã cedo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωί̈α, ας, ἡ</td><td>substantivo feminino</td><td>manhã, manhã cedo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-17\" data-source=\"BDAG\" data-search=\"πρωί̈θεν advérbio (desde a) manhã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωί̈θεν</td><td>advérbio</td><td>(desde a) manhã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-18\" data-source=\"BDAG\" data-search=\"πρώϊμος adjetivo, remissão ver πρόϊμος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρώϊμος</td><td>adjetivo, remissão</td><td>ver πρόϊμος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-19\" data-source=\"BDAG\" data-search=\"πρωϊνός, ή, όν adjetivo matutino, da manhã BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρωϊνός, ή, όν</td><td>adjetivo</td><td>matutino, da manhã</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0309-20\" data-source=\"BDAG\" data-search=\"πρῷρα substantivo feminino proa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πρῷρα</td><td>substantivo feminino</td><td>proa</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0309-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφέρω</span> 2 aor. <span class=\"greek\">προήνεγκον</span> (-<span class=\"greek\">κα</span>) (Hom. e outros; ins., pap., LXX; TestJob 11:1) acerca da produtividade, produzir algo, dar como fruto (a terra) produz <span class=\"greek\">τοὺς</span> <span class=\"greek\">κάρπους</span> GJs 3:3; acerca de trazer algo à luz (Appian, Syr. 59 §309; Jos., Bell. 1, 671) <span class=\"greek\">τὶ</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> (Alciphron 4, 13, 15; Pr 10:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:45ab</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφητεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφητεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">προφήτης</span>; Lucian, Alex. 40; 60; Heliod. 1, 22, 7; 1, 33, 2; 2, 27, 1; Ps.-Callisth. 2, 1, 3 [ofício profético]; CIG 2880, 4–6; 2881, 4; 5; OGI 494, 8f; PTebt 294, 8; 295, 10; LXX, Test12Patr; AscIs 3:21 e 31; Philo, Joseph., Just.; Ath. 9, 2)</p><p class=\"entry-text\">① ato de interpretar a vontade ou o propósito divino, atividade profética <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προφητείας</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:6</a>. <span class=\"greek\">μισθοὺς</span> <span class=\"greek\">λαμβάνει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προφητείας</span> <span class=\"greek\">αὐτοῦ</span> ele aceita remuneração por sua atividade como profeta Hm 11:12.</p><p class=\"entry-text\">② o dom de interpretar a vontade ou o propósito divino, dom de profetizar (Iren. 1, 13, 4 [Harv. I 120, 4]), de Raabe 1 Cl 12:8. Dos cristãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:10</a>; 13:2, 8 v.l.; 14:22. O pl. acerca de diversos tipos e graus de dons proféticos 13:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:20</a> (aqui a acepção 3b também é provável). <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. o espírito de profecia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:10</a>.</p><p class=\"entry-text\">③ o enunciado de quem interpreta a vontade ou o propósito divino, profecia (Jos., Ant. 9, 119; Just., D. 30, 2; 54, 2 e outros. Da Sibila: Theoph. Ant. 2, 36 [p. 190, 10]).</p><p class=\"entry-text\">ⓐ acerca de declaração inspirada do AT (Orig., C. Cels. 1, 51, 23; Hippol., Ref. 6, 19, 7; Theoph. Ant. 3, 25 [p. 256, 20]) <span class=\"greek\">ἡ</span> <span class=\"greek\">προφητεία</span> <span class=\"greek\">Ἠσαί̈ου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:14</a> (Just.. D. 50, 2 e outros). <span class=\"greek\">αἱ</span> <span class=\"greek\">προφητεῖαι</span> ao lado de <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">Μωσέως</span> (<span class=\"greek\">Μωϋσέως</span> é melhor; v. Bihlmeyer p. xxxvi) ISm 5:1. Em geral, de enunciados do AT <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:20f</a> (mas P72 parece distinguir profecia e escrito do AT: <span class=\"greek\">προφητεία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γραφή</span>); B 13:4 (Gen. 48:11; Just., A I, 54, 7 <span class=\"greek\">Μωϋσέως</span>).</p><p class=\"entry-text\">ⓑ acerca de declarações inspiradas de profetas cristãos <span class=\"greek\">ἐν</span> <span class=\"greek\">προφητείᾳ</span> sob a forma de um enunciado profético <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:20</a> (v. 2 acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:18</a>; 4:14. <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. as palavras da profecia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:3</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βιβλίου</span> <span class=\"greek\">τούτου</span> as palavras da profecia neste livro 22:7, 10, 18. <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">βιβλίου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ταύτης</span> as palavras deste livro de profecia v. 19.—DELG s.v. <span class=\"greek\">φημί</span> II A. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφητεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφητεύω</span> (<span class=\"greek\">προφήτης</span>) imperf. <span class=\"greek\">ἐπροφήτευον</span>; fut. <span class=\"greek\">προφητεύσω</span>; 1 aor. <span class=\"greek\">ἐπροφήτευσα</span> (também <span class=\"greek\">προεφήτ</span>. [1 Km 18:10; Just.] v.l.; sobre o aumento v. B-D-F §69, 4; W-S. §12, 6; Mlt-H. 192). Pass.: aor. 3 sing. <span class=\"greek\">προεφητεύθη</span>; perf. 3 sing. <span class=\"greek\">πεπροφήτευται</span>; mais-que-perf. 3 sing. <span class=\"greek\">ἐπεπροφήτευτο</span> (todos em Just.) (Pind., Hdt.+; Diod S 17, 51, 1; Ps.-Aristot., De Mundo 1, 391a, 16 <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">θείῳ</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">ὄμματι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">θεῖα</span> <span class=\"greek\">καταλαβοῦσα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἀνθρώποις</span> <span class=\"greek\">προφητεύουσα</span>=a alma compreendendo as coisas divinas com seu olho divino e interpretando-as para os seres humanos; Plut., Mor. 412b; Lucian, VH 2, 33; Herodian 5, 5, 10; OGI 473, 2; 530, 9; Gnomon [= BGU V] 93; LXX; pseudepígr., Philo, Joseph., Just. Primariamente: ‘servir de intérprete da vontade ou do propósito divino’; a referência ao futuro pode ou não estar indicada)</p><p class=\"entry-text\">① proclamar uma revelação inspirada, profetizar, abs. (Diod S 17, 51, 1; Jos., Ant. 5, 348) <span class=\"greek\">οὐ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">ἐπροφητεύσαμεν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:22</a> (v. Jer 34:15).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:17f</a> (Jo 3:1); 19:6; 21:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:4f</a> (com <span class=\"greek\">προσεύχεσθαι</span>); 13:9; 14:1, 3–5, 24, 31, 39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:3</a>; B 16:9; Hm 11:12. De enunciados da Escritura B 9:2; Hv 2, 3, 4 (a citação aqui do livro de Eldade e Modate não diz respeito ao futuro; naturalmente isso não exclui a possibilidade de que esses ‘profetas’ praticassem sua arte no sentido da acepção 3 abaixo).</p><p class=\"entry-text\">② dizer algo que está oculto à vista, dizer, revelar, acerca do desafio escarnecedor dirigido a Jesus que reduz a atividade inspirada à clarividência <span class=\"greek\">προφήτευσον</span> <span class=\"greek\">ἡμῖν</span>, <span class=\"greek\">Χριστέ</span>, <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παίσας</span> <span class=\"greek\">σε</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:68</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.65\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:65</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.64\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:64</a> (cf. a zombaria dirigida ao adivinho Euno em Diod S 34/35, 2, 46 [GRudberg, ZNW 24, 1925, 307–9] e WCvanUnnik, ZNW 29, ’30, 310f; PBenoit, OCullmann Festschr., ’62, 92–110).</p><p class=\"entry-text\">③ predizer algo que pertence ao futuro, predizer, profetizar (SibOr 3, 163; 699 e outros; Iren. 1, 13, 3 [Harv I 118, 15]; Orig., C. Cels. 6, 47, 11. <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">προλέγειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐσόμενα</span> Hippol., Ref. 9, 27, 3), de profetas e do povo de Deus em tempos passados: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:13</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> profetizar acerca de alguém ou de algo (2 Ch 18:7; AscIs 2:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:10</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> profetizar com referência a alguém B 5:6. Também <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> 5:13. Seguido de discurso direto 12:10. <span class=\"greek\">ἐπροφήτευσεν</span> <span class=\"greek\">λέγων</span>, seguido de discurso direto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.67\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:67</a> (o pai de João Batista); também <span class=\"greek\">τινί</span> a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 14</a> (Enoque). Com <span class=\"greek\">ὅτι</span> seguinte: do sumo sacerdote (v. Jos., Bell. 1, 68f=Ant. 13, 299f; v. também 282f; CHDodd, OCullmann Festschr., ’62, 134–43.—Segundo Diod S 40, 3, 5; 6 os <span class=\"greek\">Ἰουδαῖοι</span> consideravam o <span class=\"greek\">ἀρχιερεύς</span> um <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">προσταγμάτων</span>. Tudo o que lhe é revelado ele comunica ao povo em suas assembleias [<span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐκκλησίας</span>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:51</a> (cf. referência a Elias <span class=\"greek\">περὶ</span> <span class=\"greek\">Ὀχοζείου</span> <span class=\"greek\">ὅτι</span> AscIs 2:14). Do autor de Rv <span class=\"greek\">πρ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">λαοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:11</a>. De falsos videntes cristãos Hm 11:13 (v. 11:2 sobre sua identidade: falam com pessoas que lhes perguntam <span class=\"greek\">τί</span> <span class=\"greek\">ἄρα</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">αὐτοῖς</span>).—DELG s.v. <span class=\"greek\">φημί</span> II A. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφήτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφήτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πρό</span>, <span class=\"greek\">φημί</span>; ind., Hdt.+. Exemplos em Fascher, v. o fim deste verbete) proclamador ou expositor de assuntos ou questões divinas que normalmente não poderiam ser conhecidos senão por revelação especial (tipo de pessoa comum na sociedade politeísta, v. p. ex. Plato Com. [V/IV a.C.] 184 [Orfeu]; Ephor. [IV a.C.]: 70 Fgm. 206 Jac., de Amom, igualmente Diod S 17, 51, 1; Plut., Numa 9, 8 o pontifex maximus como <span class=\"greek\">ἐξηγητὴς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">προφήτης</span>; Dio Chrys. 19 [36], 42 <span class=\"greek\">πρ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Μουσῶν</span>; Ael. Aristid. 45, 4 K.=8 p. 83 D.: <span class=\"greek\">προφῆται</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>; 45, 7 K.=8 p. 84 D.; 46 p. 159 D.: <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἱερεῖς</span>, igualmente Himerius, Or. 8 [Or. 23], 11; Alciphron 4, 19, 9 <span class=\"greek\">Διονύσου</span> <span class=\"greek\">πρ</span>.; Himerius, Or. 38 [Or. 4], 9 Sócrates como <span class=\"greek\">Μουσῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἑρμοῦ</span> <span class=\"greek\">προφήτης</span>, Or. 48 [Or. 14], 8 <span class=\"greek\">προφῆται</span> dos egípcios [sobre a função do profeta egípcio v. HKees, Der berichtende Gottesdiener: ZASA 85, ’60, 138–43]; PGM 3, 256).</p><p class=\"entry-text\">① pessoa inspirada para proclamar ou revelar a vontade ou o propósito divino, profeta</p><p class=\"entry-text\">ⓐ acerca das personalidades proféticas do AT que trazem uma mensagem de Deus (cf. GHölscher, Die Profeten v. Israel 1914; BDuhm, Israels Propheten2 1922; HGunkel, Die Proph. 1917; LDürr, Wollen u. Wirken der atl. Proph. 1926; JSeverijn, Het Profetisme 1926; HHertzberg, Prophet u. Gott 1923; JHempel, Gott u. Mensch im AT2 ’36, 95–162). Alguns são mencionados nominalmente (Moisés: Orig., C. Cels. 6, 21, 8): Jeremias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:17</a>; 27:9. Isaías (Did., Gen. 52, 13) 3:3; 4:14; 8:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:23</a>; 12:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:25</a> e outros. Joel 2:16. Jonas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:39</a>. Daniel 24:15. Elias, Eliseu, Ezequiel 1 Cl 17:1. Eliseu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:27</a>; AcPlCor 2:32; Samuel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:20</a>; cf. 3:24. Davi 2:30 (ApcSed 14:4; Just., A I, 35, 6; JFitzmyer, CBQ 34, ’72, 332–39). Até Balaão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:16</a>.—Às vezes a identidade do profeta é conhecida somente pelo contexto, ou simplesmente se espera que o leitor saiba quem se tem em vista; semelhantemente, um escritor grego diz <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιητής</span>, certo de que será compreendido corretamente (Antig. Car. 7 [Hom. Hymn to Hermes]; Diod S 1, 12, 9; 3, 66, 3 e outros [Homero]; escólio a Nicander, Ther. 452; Ps.-Dicaearchus p. 147 F. [Il. 2, 684]; Steph. Byz. s.v. <span class=\"greek\">Χαλκίς</span> [Il. 2, 537]—Did., Gen. 25, 20 [Ageu]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:22</a> (Isaías, como Just., D. 89, 3); 2:5 (Miqueias), 15 (Oseias); 21:4 (Zacarias); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.48\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:48</a> (Isaías). V. B 6:2, B 4, B 6f, B 10, B 13; B 11:2, B 4, B 9; B 14:2, B 7–9.—O pl. <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span> reúne os profetas numa só categoria (Iren. 1, 7, 3 [Harv. I 63, 2]; cf. Theoph. Ant. 1, 14 [p. 88, 14]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:23</a>; 5:12; 16:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:15b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.70\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:70</a>; 6:23; 13:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:45</a> (com Moisés); 8:52f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:21</a>; 7:52; 10:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:32</a> (com Davi e Samuel); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:10</a> (classificado em e abaixo por ESelwyn, 1 Pt ’46, ad loc. e 259–68); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:2</a>; 1 Cl 43:1 (<span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λοιποί</span> <span class=\"greek\">πρ</span>.); B 1:7; IMg 9:3; IPhld 5:2; AcPl Ha 8, 16; AcPlCor 1:10; 2:9 e 36. <span class=\"greek\">οἱ</span> <span class=\"greek\">θειότατοι</span> <span class=\"greek\">πρ</span>. IMg 8:2; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀγαπητοὶ</span> <span class=\"greek\">πρ</span>. IPhld 9:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀρχαῖοι</span> <span class=\"greek\">πρ</span>. (Jos., Ant. 12, 413) D 11:11b. V. 2 abaixo acerca das figuras proféticas em associação com suas produções escritas.</p><p class=\"entry-text\">ⓑ João Batista (Just., D. 49, 3) também é chamado profeta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:5</a>; 21:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.76\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:76</a> (<span class=\"greek\">προφήτης</span> <span class=\"greek\">ὑψίστου</span>; cf. OGI 756, 2 <span class=\"greek\">τὸν</span> <span class=\"greek\">προφήτην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγιωτάτου</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ὑψίστου</span>); 20:6, mas Jesus declarou que ele era superior aos profetas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:26</a>.</p><p class=\"entry-text\">ⓒ Jesus aparece como profeta (FGils, Jésus prophète [sinóticos], ’57 [literatura]) apreciado por seu conhecimento surpreendente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:19</a> e pela capacidade de realizar milagres 9:17. <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">Ἰησοῦς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:11</a>. Cf. v. 46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:15a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:16</a> (<span class=\"greek\">πρ</span>. <span class=\"greek\">μέγας</span>), 39; 13:33; 24:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:52</a>. Aplica-se-lhe este provérbio: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">προφήτης</span> <span class=\"greek\">ἄτιμος</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πατρίδι</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:4</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:44</a>; Ox 1:10f (GTh 31; EPreuschen, Das Wort v. verachteten Proph.: ZNW 17, 1916, 33–48). Também se julgava que ele fosse um dos antigos profetas que voltara à vida: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:28</a>. <span class=\"greek\">πρ</span>. <span class=\"greek\">τις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀρχαίων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:8</a>, 19.—Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:22f</a> e 7:37 (cf. 1QS 9:11), Dt 18:15, 19 é interpretado com referência ao Messias e, portanto, a Jesus (HSchoeps, Theol. u. Geschichte des Judenchristentums ’49, 87–98).—Para J, Jesus é <span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span> o Profeta 6:14; 7:40, título honorífico que o Batista não reivindica para si 1:21, 25 (v. excurs. no Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:21</a>; HFischel, JBL 65, ’46, 157–74). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:39</a> v.l.—RMeyer, Der Proph. aus Galiläa ’40; PDavies, Jesus and the Role of the Prophet: JBL 64, ’45, 241–54; AHiggins, Jesus as Proph.: ET 57, ’45/46, 292–94; FYoung, Jesus the Proph.: JBL 68, ’49, 285–99.—RSchnackenburg, D. Erwartung des ‘Propheten’ nach dem NT u. Qumran: Studia Evangelica ’59, 622, n. 1; HBraun, Qumran u. das NT, I, ’66, 100–106.</p><p class=\"entry-text\">ⓓ também acerca de outras pessoas, sem excluir os profetas propriamente ditos, que proclamam a mensagem divina com preparação especial e missão especial (1 Macc 4:46; 14:41; Hippol., Ref. 1, prol. 10): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:9</a> e paralelos (v. 1b acima); 13:57 e paralelos (v. 1c acima); 23:30, 37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:24</a> (sobre <span class=\"greek\">προφῆται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βασιλεῖς</span> v. Boll 136–42); 13:33f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.52\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:52</a>. Os dois profetas de Deus nos últimos tempos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:10</a> (v. <span class=\"greek\">μάρτυς</span> 2c e <span class=\"greek\">Πέτρος</span>, fim). Em várias das passagens já mencionadas (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:15</a> [v. a acima]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:30</a>, 37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.52\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:52</a>), assim como em outras (v. abaixo acerca de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:49</a> [OSeitz, TU 102, ’68, 236–40]), diversos compatriotas de Jesus são assassinos de profetas (cf. 3 Km 19:10, 14; Jos., Ant. 9, 265). HJSchoeps, D. jüd. Prophetenmorde ’43.—Jesus também envia a seu próprio povo <span class=\"greek\">προφήτας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σοφούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:34</a> ou <span class=\"greek\">πρ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἀποστόλους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:49</a>; v. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:41</a> (<span class=\"greek\">πρ</span>. ao lado de <span class=\"greek\">δίκαιος</span>, como 13:17). Isso nos conduz a</p><p class=\"entry-text\">ⓔ cristãos, que são dotados do dom de <span class=\"greek\">προφητεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:29</a>, 32, 37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:6</a>, 9; D 10:7; 13:1, 3f, 6. Com <span class=\"greek\">ἀπόστολοι</span> (Celsus 2, 20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:20</a> (embora aqui a referência possa ser aos profetas do AT, como certamente é o caso em Pol 6:3. Segundo PJoüon, RSR 15, 1925, 534f, <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀπ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">πρ</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:20</a> referem-se às mesmas pessoas); 3:5; D 11:3. <span class=\"greek\">πρ</span>. encontra-se entre <span class=\"greek\">ἀπόστολοι</span> e <span class=\"greek\">διδάσκαλοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:28f</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:11</a>. Com <span class=\"greek\">διδάσκαλοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:1</a>; D 15:1f. Com <span class=\"greek\">ἅγιοι</span> e <span class=\"greek\">ἀπόστολοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:20</a>. Com <span class=\"greek\">ἅγιοι</span> 11:18; 16:6; 18:24. Profetas predizem acontecimentos futuros (cf. Pla., Charm. 173c <span class=\"greek\">προφῆται</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μελλόντων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:27</a> (v. v. 28); 21:10 (v. vv. 11f). Profetas verdadeiros e falsos: <span class=\"greek\">τὸν</span> <span class=\"greek\">προφήτην</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ψευδοπροφήτην</span> Hm 11:7; v. vv. 9 e 15 (o restante deste ‘mandamento’ também trata deste assunto); D 11:7–11.—Harnack, Lehre der Zwölf Apostel 1884, 93ff; 119ff, Mission4 I 1923, 344f; 362ff; Rtzst., Mysterienrel.3 236–40; v. ESelwyn sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:10</a> em 1a acima; HGreeven, Propheten, Lehrer, Vorsteher b. Pls: ZNW 44, ’52/53, 3–15.</p><p class=\"entry-text\">ⓕ Somente em uma passagem de nossa literatura um politeísta é chamado ‘profeta’, a saber, o poeta cuja descrição dos cretenses é mencionada em Tit 1:12: <span class=\"greek\">ἴδιος</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">προφήτης</span> seu próprio profeta (dos cretenses) (v. <span class=\"greek\">ἀργός</span> 2).</p><p class=\"entry-text\">② por metonímia, os escritos dos profetas. O profeta também representa seu livro <span class=\"greek\">ἀνεγίνωσκεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">προφήτην</span> <span class=\"greek\">Ἠσαί̈αν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:28</a>, 30; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:2</a>. <span class=\"greek\">λέγει</span> (<span class=\"greek\">κύριος</span>) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">προφήτῃ</span> B 7:4. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἄλλῳ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">λέγει</span> 11:6. V. 6:14; 12:1 e 4. Pl. dos profetas como uma divisão da Escritura: <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> (v. 2 Macc 15:9; Mel., HE 4, 26, 13, P. 72, 530) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:13</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:15</a>; 24:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:21</a>; Dg 11:6. <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:29</a>, 31. Cf. também 24:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:23</a>. <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">γεγραμμένα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">νόμῳ</span> <span class=\"greek\">Μωϋσέως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">προφήταις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ψαλμοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:44</a>. Ocasionalmente <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span>, por si só, pode significar toda a Escritura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.45\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:45</a> (v. JHänel, Der Schriftbegriff Jesu 1919, 21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:1</a> (v. CBüchel, Der Hb u. das AT: StKr 79, 1906, 508–91).—<span class=\"greek\">οἱ</span> <span class=\"greek\">πρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17</a>; 7:12; 22:40 (todos os três com <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span>) refere-se inequivocamente ao conteúdo dos livros proféticos.—EFascher, <span class=\"greek\">Προφήτης</span>. Eine sprach-und religionsgeschichtliche Untersuchung 1927; GFohrer, TRu 19, ’51, 277–346; 20. ’52. 193–271, 295–361; JLindblom, Prophecy in Ancient Israel ’67; DAune, Prophecy ’83; ASchwemer ZTK 96, ’99, 320--50 (profeta como mártir); Pauly-W. XXIII 797ff; Kl. Pauly IV, 1183f; BHHW III 1496–1514.—DELG s.v. <span class=\"greek\">φημί</span> II A. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφητικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφητικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">προφήτης</span>; Lucian, Alex. 60; Philo, Migr. Abr. 84 e outros; Just., Mel., Ath.; PGM 1, 278; 4, 933) relativo à interpretação inspirada da vontade divina, profético <span class=\"greek\">γραφαὶ</span> <span class=\"greek\">πρ</span>. os escritos dos profetas=o AT <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:26</a> (cf. AcPh 77 [Aa II/2, 30, 6]). <span class=\"greek\">ὁ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">λόγος</span> (Philo, Plant. 117; TestSol 1:12 D <span class=\"greek\">ἡ</span>-<span class=\"greek\">κὴ</span> <span class=\"greek\">ῥῆσις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:19</a> (sobre a verdadeira palavra profética em oposição à falsa [v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:1</a>] cf. Pind., P. 10, 65f); 2 Cl 11:2 (a origem da palavra profética que se segue é desconhecida); AcPl Ha 8, 27. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">πνεύματος</span> Hm 11:9 (<span class=\"greek\">πρ</span>. <span class=\"greek\">πνεῦμα</span>, como Philo, Fuga 186; Just., A I, 38, 1; Ath. 10, 3). De Policarpo <span class=\"greek\">διδάσκαλος</span> <span class=\"greek\">ἀποστολικὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προφητικός</span> MPol 16:2.—DELG s.v. <span class=\"greek\">φημί</span> II A. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφητικῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφητικῶς</span> adv. de <span class=\"greek\">προφητικός</span>, profeticamente <span class=\"greek\">εἰπεῖν</span> falar profeticamente (seguido de discurso direto) MPol 12:3 (Ath. 10, 3 após discurso direto).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφῆτις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφῆτις</span>, <span class=\"greek\">ιδος</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">προφήτης</span>; Eur., Pla.+; Diod S 14, 13, 3 [Pítia]; ins.: CIG 3796; InsMagn 122d, 3 [se corretamente restaurado]; LXX: Ex 15:20 Miriã; Judg 4:4 Débora e outros; Philo; Jos., Ant. 10, 59; SibOr 3, 818; Sextus 441) a forma correspondente a <span class=\"greek\">προφήτης</span> (v. acima), profetisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:36</a>. De uma Jezabel que desencaminhava a igreja em Tiatira <span class=\"greek\">ἡ</span> <span class=\"greek\">λέγουσα</span> <span class=\"greek\">ἑαυτὴν</span> <span class=\"greek\">προφῆτιν</span> que se chama a si mesma profetisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:20</a> (v. <span class=\"greek\">Ἰεζάβελ</span> e a literatura ali citada).—DELG s.v. <span class=\"greek\">φημί</span> II A. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφθάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφθάνω</span> fut. 3 sing. <span class=\"greek\">προφθάσει</span> LXX; 1 aor. <span class=\"greek\">προέφθασα</span>; perf. 3 sing. <span class=\"greek\">προέφθακεν</span> 1 Macc 10:23 (Aeschyl., Pla. e outros; Plut., Mor. 806f; LXX) acerca de prioridade temporal</p><p class=\"entry-text\">① estar à frente de alguém em alguma atividade, preceder, vir antes, antecipar-se, com ac. e part. seguinte (Aristoph., Eccl. 884; B-D-F §414, 4; Rob. 1120; <span class=\"greek\">φθάνω</span> com part.: EpArist 137) <span class=\"greek\">προέφθασεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">λέγων</span> ele lhe falou primeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:25</a>.</p><p class=\"entry-text\">② fazer algo em um momento anterior a outro momento, fazer antes/previamente, com inf. seguinte (B-D-F §392, 2; Rob. 1120) <span class=\"greek\">ἐὰν</span> <span class=\"greek\">προφθάσῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κάμινον</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">βαλεῖν</span> se ele o tiver posto previamente (=já) na fornalha 2 Cl 8:2.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προφυλάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προφυλάσσω</span> fut. méd. <span class=\"greek\">προφυλάξομαι</span> 2 Km 22:24 (<span class=\"greek\">φύλαξ</span>; Hom. Hymns, Hdt. e outros; SIG 730, 15; PWürzburg 9, 8 [II d.C.])</p><p class=\"entry-text\">① tomar medidas de segurança de antemão, guardar, proteger <span class=\"greek\">τινά</span> alguém, ativo ITr 8:1. <span class=\"greek\">πρ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> alguém contra alguém ISm 4:1 (sobre <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> cf. 2 Km 22:24). V. também 2.</p><p class=\"entry-text\">② estar vigilante diante do perigo, estar de sobreaviso, médio (Hdt., Thu. e outros; 2 Km 22:24; SibOr 3, 733) com <span class=\"greek\">μή</span> e inf. IMg 11 (embora, em razão da analogia das duas passagens acima mencionadas, a voz média aqui possa ter sentido ativo [Diogenian., o epicurista, do século II d.C., Fgm. 4 Gercke: em Eus., PE 4, 3, 7 fim, duas vezes; e Philo, Cher. 34, a voz média significa ‘afastar algo’]; Rdm.2 79f).—DELG s.v. <span class=\"greek\">φύλαξ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προχειρίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προχειρίζω</span> em nossa literatura, como na maioria dos casos, somente como depoente médio <span class=\"greek\">προχειρίζομαι</span> 1 aor. <span class=\"greek\">προεχειρισάμην</span>. Pass.: part. aor. pl. masc. <span class=\"greek\">προχειρισθέντες</span> Da 3:22; part. perf. <span class=\"greek\">προκεχειρισμένος</span> manifestar preferência por alguém para uma tarefa, escolher para si, selecionar, designar <span class=\"greek\">τινά</span> alguém (Isocr. e outros; Polyb. 2, 43, 1; 6, 58, 3; Dionys. Hal., De Orat. Ant. 4; Plut., Galba 1056 [8, 3], Caesar 735 [58, 8]; Lucian, Tox. 10; SIG 873, 14f; OGI 339, 46; 50; pap.; 2 Macc 3:7; 8:9) seguido de inf. de finalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:14</a>. Com dois ac., de objeto e predicativo (Polyb. 1, 11, 3; Diod S 12, 27, 1; PLond 2710 recto, 5; Ex 4:13) <span class=\"greek\">προχειρίσασθαί</span> <span class=\"greek\">σε</span> <span class=\"greek\">ὑπηρέτην</span> 26:16. Pass. (<span class=\"greek\">προκεχειρισμένος</span> como UPZ 117 II, 4 [II a.C.]; BGU 1198, 2 [I a.C.]; PFay 14, 1) <span class=\"greek\">τὸν</span> <span class=\"greek\">προκεχειρισμένον</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">Χριστὸν</span> <span class=\"greek\">Ἰησοῦν</span> Cristo Jesus, que foi designado para vós, ou Jesus, que foi designado (ou destinado) para ser vosso Messias 3:20 (o dat. como em Josh 3:12; v. <span class=\"greek\">προκηρύσσω</span>).—DELG s.v. <span class=\"greek\">χείρ</span> III. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προχειροτονέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προχειροτονέω</span> (cf. <span class=\"greek\">χειροτόνος</span> ‘que estende as mãos’) part. perf. pass. <span class=\"greek\">προκεχειροτονημένος</span> escolher/designar de antemão (assim Pla., Leg. 6, 765bc e outros; Cass. Dio 50, 4; BGU 1191, 6 [I a.C.] <span class=\"greek\">τῷ</span> <span class=\"greek\">προκεχειροτονημένῳ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:41</a>.—DELG s.v. <span class=\"greek\">χείρ</span> II. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πρόχορος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πρόχορος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (encontrado no grego tardio) Prócoro, um dos sete designados para serviço especial na igreja em Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">προχωρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">προχωρέω</span> (Soph., Hdt. e outros; ins., pap., TestIss 1:11) sentido primário ‘ir para diante, avançar’, em nossa literatura somente fig. progredir quanto a estado ou condição, resultar, ter êxito, com dat. de pessoa para quem algo corre bem (Hdt. 5, 62; Thu. 4, 73, 4; Lucian, Icar. 10; PLond 358, 13 [II d.C.] <span class=\"greek\">προχωρεῖν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄνομα</span>; Jos., Vi. 122) <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ὅλως</span> <span class=\"greek\">προχωρεῖ</span> absolutamente nada lhes sai bem Hs 6, 3, 5.—DELG s.v. <span class=\"greek\">χώρα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρύμνα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρύμνα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; pap.) a parte posterior de uma embarcação, popa (oposto a <span class=\"greek\">πρῷρα</span>) <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πρύμνῃ</span> <span class=\"greek\">καθεύδων</span> ele dormia na popa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:38</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:29</a> (WStammler, AG 27 in nautischer Beleuchtung etc., ’31, 3–15; contra ele FBruce, Acts3, ’90, 523, com evidências de navios lançando âncora pela popa) (com <span class=\"greek\">πρῷρα</span> como X., An. 5, 8, 20; Ael. Aristid. 44, 13 K.=17 p. 405 D.).—DELG s.v. <span class=\"greek\">πρυμνός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωί̈</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωί̈</span> adv. de tempo (cf. <span class=\"greek\">πρό</span>; Hom.+; nos escritores áticos como <span class=\"greek\">πρῴ</span>) na parte inicial do período de luz do dia, cedo, de manhã cedo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:3</a>; 21:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:35</a>; 11:20; 16:9; Hs 9, 11, 2 (oposto a <span class=\"greek\">ὀψέ</span>). Como a quarta vigília da noite (depois de <span class=\"greek\">ὀψὲ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">μεσονύκτιον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἀλεκτοροφωνίας</span>) é o tempo das três às seis horas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:35</a>. <span class=\"greek\">εὐθὺς</span> <span class=\"greek\">πρ</span>. logo que chegou a manhã 15:1. <span class=\"greek\">ἅμα</span> <span class=\"greek\">πρ</span>. (<span class=\"greek\">ἅμα</span> 2, fim) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:1</a>; <span class=\"greek\">λίαν</span> <span class=\"greek\">πρ</span>. com dat., do dia, muito cedo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:2</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἑσπέρας</span> da manhã até o anoitecer <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:23</a> (cf. Jos., Ant. 13, 97). <span class=\"greek\">πρωὶ̈</span> <span class=\"greek\">σκοτίας</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">οὔσης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:1</a>. <span class=\"greek\">ἦν</span> <span class=\"greek\">πρ</span>. era de manhã cedo (B-D-F §129; 434, 1) 18:28. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρωί̈</span> é igualmente um adv. (PSI 402, 10 [III a.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">πρωὶ̈</span> <span class=\"greek\">εὐθέως</span>; LXX; TestAbr B 2 p. 106, 7 [Stone p. 60] <span class=\"greek\">τῷ</span> <span class=\"greek\">πρωί</span>; TestNapht 1:3; JosAs 9:4; ApcEsdr 4:29; B-D-F §160; 161, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:21</a> D. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρωί̈</span> ao aproximar-se a manhã <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:1</a> v.l.; em seu lugar outra v.l. tem <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πρ</span>.—Billerb. I 688–91; TMartin, BR 38, ’93, 55–69. B. 960. DELG s.v. <span class=\"greek\">πρώην</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωί̈α, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωί̈α</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">πρωί̈</span>; Diod S; CIG 1122, 16; BGU 1206, 20 [28 a.C.]; PLond I, 131, 16 p. 170; 461 p. 183 [78/79 d.C.]; III, 1177, 66 p. 183 [113 d.C.] <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πρωί̈ας</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">ὀψέ</span>; LXX; ParJer; EpArist 304; Philo, Vi. Cont. 89; Jos., Ant. 7, 164; Ar. [Milne 76, 34] <span class=\"greek\">κατὰ</span> <span class=\"greek\">πρώϊας</span>.—Na verdade, o fem. de <span class=\"greek\">πρώϊος</span> [desde Hom.], subent. <span class=\"greek\">ὥρα</span>) parte inicial do período de luz do dia, manhã (cedo), <span class=\"greek\">πρωί̈ας</span> <span class=\"greek\">γενομένης</span> quando era manhã (ParJer 4:1; Syntipas p. 49, 17; 53, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:1</a>; 1 Cl 43:5. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:28</a> v.l.; 21:4. Gen. de tempo <span class=\"greek\">πρωί̈ας</span> de manhã (cedo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:18</a> v.l.; GPt 9:34.—B. 994. DELG s.v. <span class=\"greek\">πρώην</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωί̈θεν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωί̈θεν</span> (<span class=\"greek\">πρωί̈</span>) adv. de tempo (LXX; Herodian, Gr. I 501, 9) (desde a) manhã, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πρ</span>. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἑσπέρας</span> 1 Cl 39:5 (Job 4:20). A terminação -<span class=\"greek\">θεν</span> tendia a perder sua força e tornar-se desprovida de significado em muitos casos: v. exemplos B-D-F §104, 2; Rob. 300; MLejeune, Les adverbes grecs en-<span class=\"greek\">θεν</span> ’39, mas no caso de <span class=\"greek\">πρ</span>. a força tradicional aparentemente ainda era sentida, porém reforçada pela prep. <span class=\"greek\">ἀπό</span> (cf. Georg. Mon. 179, 16).—DELG s.v. <span class=\"greek\">πρώην</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρώϊμος</h1><div class=\"entry-meta\"><span>adjetivo, remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρώϊμος</span> v. <span class=\"greek\">πρόϊμος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρωϊνός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρωϊνός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (PCairZen 207, 36 [III a.C.]; Babrius 124, 17 com a v.l. <span class=\"greek\">προϊνων</span> do cód. V. [L-P.]; Plut., Mor. 726e; Athen. 1, 19 p. 11c; LXX) relativo à manhã cedo, matutino, pertencente à manhã <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀστὴρ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πρ</span>. a estrela da manhã, Vênus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:28</a>; 22:16 (v. <span class=\"greek\">προϊνός</span> para vv.ll.).—DELG s.v. <span class=\"greek\">πρώην</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0309-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πρῷρα</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πρῷρα</span> (Hom. e outros; PSI 382, 2 [III a.C.]; PEdg 9 [=Sb 6715], 15 [257 a.C.]. Sobre o <span class=\"greek\">ι</span> subscrito B-D-F §26; Mlt-H. 84), <span class=\"greek\">ης</span> (PGM 8, 40; B-D-F §43, 1; Mlt-H. 118), <span class=\"greek\">ἡ</span>, a parte anterior de uma embarcação, proa (oposto a <span class=\"greek\">πρύμνα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:30</a>, 41 (cf. a descrição Pind., P. 10, 51f; v. <span class=\"greek\">πρύμνα</span>). DELG. M-M.</p></section></article>"};
